#include <iostream>

class SimpleDate {
public:
    explicit SimpleDate(int m = 1, int d = 1, int y = 2000)
        : month(m), day(d), year(y) {}

    void print() const {
        std::cout << month << '/' << day << '/' << year;
    }

private:
    int month;
    int day;
    int year;
};

int main() {
    SimpleDate date1{7, 4, 2004};
    SimpleDate date2; // defaults to 1/1/2000

    std::cout << "date1 = ";
    date1.print();
    std::cout << "\ndate2 = ";
    date2.print();

    date2 = date1; // default memberwise assignment

    std::cout << "\n\nAfter default memberwise assignment, date2 = ";
    date2.print();
    std::cout << std::endl;

    return 0;
}

#include <iostream>

class Time {
public:
    explicit Time(int h = 0, int m = 0, int s = 0) {
        setTime(h, m, s); // Constructor can call non-const helper
    }

    void setTime(int h, int m, int s) {
        hour = (h >= 0 && h < 24) ? h : 0;
        minute = (m >= 0 && m < 60) ? m : 0;
        second = (s >= 0 && s < 60) ? s : 0;
    }

    void setHour(int h) {
        hour = (h >= 0 && h < 24) ? h : 0;
    }

    int getHour() const { return hour; }
    int getMinute() const { return minute; }

    void printUniversal() const {
        std::cout << (hour < 10 ? "0" : "") << hour << ":"
                  << (minute < 10 ? "0" : "") << minute << ":"
                  << (second < 10 ? "0" : "") << second;
    }

private:
    int hour{0};
    int minute{0};
    int second{0};
};

int main() {
    Time wakeUp{6, 45, 0};        // non-const object
    const Time noon{12, 0, 0};     // const object

    wakeUp.setHour(18);            // non-const obj calls non-const method (OK)
    std::cout << "wakeUp hour: " << wakeUp.getHour() << "\n"; // non-const obj calls const method (OK)

    std::cout << "noon minute: " << noon.getMinute() << "\n"; // const obj calls const method (OK)
    std::cout << "noon universal: ";
    noon.printUniversal();        // const obj calls const method (OK)
    std::cout << "\n";

    // noon.setHour(12); // COMPILER ERROR: cannot call non-const method on const object
    return 0;
}

#include <iostream>
#include <string>

class Date {
public:
    explicit Date(int m = 1, int d = 1, int y = 1900)
        : month(m), day(d), year(y) {
        std::cout << "Date constructor: " << month << '/' << day << '/' << year << '\n';
    }

    ~Date() {
        std::cout << "Date destructor: " << month << '/' << day << '/' << year << '\n';
    }

    void print() const {
        std::cout << month << '/' << day << '/' << year;
    }

private:
    int month;
    int day;
    int year;
};

class Employee {
public:
    Employee(const std::string& first, const std::string& last,
             const Date& dateOfBirth, const Date& dateOfHire)
        : firstName{first},
          lastName{last},
          birthDate{dateOfBirth},
          hireDate{dateOfHire} {
        std::cout << "Employee constructor: " << firstName << ' ' << lastName << '\n';
    }

    ~Employee() {
        std::cout << "Employee destructor: " << firstName << ' ' << lastName << '\n';
    }

    void print() const {
        std::cout << lastName << ", " << firstName << " Hired: ";
        hireDate.print();
        std::cout << "  Birthday: ";
        birthDate.print();
        std::cout << '\n';
    }

private:
    std::string firstName;
    std::string lastName;
    const Date birthDate;
    const Date hireDate;
};

int main() {
    Date birth{7, 24, 1989};
    Date hire{3, 12, 2018};

    {
        Employee emp{"Grace", "Hopper", birth, hire};
        std::cout << "\nEmployee details:\n";
        emp.print();
        std::cout << "\nExiting inner block:\n";
    }

    std::cout << "Returned to main block\n";
    return 0;
}
